package cn.zhuatech.dealer.deep;import cn.zhuatech.dealer.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dealer-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/dealers")ApiResponse<?> dealer(@Valid @RequestBody DeepDomainService.DealerRequest r){return ApiResponse.ok(s.createDealer(r));}@PostMapping("/dealers/{id}/submit")ApiResponse<?> submit(@PathVariable Long id){return ApiResponse.ok(s.submit(id));}@PostMapping("/dealers/{id}/authorizations")ApiResponse<?> authorize(@PathVariable Long id,@Valid @RequestBody DeepDomainService.AuthorizationRequest r){return ApiResponse.ok(s.authorize(id,r));}@PostMapping("/orders")ApiResponse<?> order(@Valid @RequestBody DeepDomainService.OrderRequest r){return ApiResponse.ok(s.order(r));}@PostMapping("/orders/{id}/fulfill")ApiResponse<?> fulfill(@PathVariable Long id){return ApiResponse.ok(s.fulfill(id));}@PostMapping("/orders/{id}/rebates")ApiResponse<?> claim(@PathVariable Long id,@Valid @RequestBody DeepDomainService.RebateRequest r){return ApiResponse.ok(s.claim(id,r));}}
